extends RefCounted

var triangles: Array = []
var astar: AStar2D = AStar2D.new()
var centroids: PackedVector2Array = []

func build(boundary: PackedVector2Array, holes: Array) -> void:
    triangles.clear()
    astar.clear()
    centroids.clear()

    # Simple strategy: 
    # 1. Triangulate the boundary + holes using Delaunay on all points.
    # 2. Filter triangles: keep only those whose centroid is inside the boundary
    #    AND outside all holes.

    var all_points: PackedVector2Array = boundary
    for hole in holes:
        for p in hole:
            all_points.append(p)

    var delaunay_indices = Geometry2D.triangulate_delaunay(all_points)

    var temp_triangles = []
    for i in range(0, delaunay_indices.size(), 3):
        var p1 = all_points[delaunay_indices[i]]
        var p2 = all_points[delaunay_indices[i+1]]
        var p3 = all_points[delaunay_indices[i+2]]

        var centroid = (p1 + p2 + p3) / 3.0

        # Keep if inside boundary AND NOT inside any hole
        if Geometry2D.is_point_in_polygon(centroid, boundary):
            var in_hole = false
            for hole in holes:
                if Geometry2D.is_point_in_polygon(centroid, hole):
                    in_hole = true
                    break
            if not in_hole:
                temp_triangles.append([p1, p2, p3])

    triangles = temp_triangles

    # Adjacency
    for i in range(triangles.size()):
        astar.add_point(i, get_centroid(triangles[i]))

    for i in range(triangles.size()):
        for j in range(i + 1, triangles.size()):
            if are_adjacent(triangles[i], triangles[j]):
                astar.connect_points(i, j)

func get_triangles() -> Array:
    return triangles

func get_adjacency() -> Array:
    var adj = []
    for i in range(triangles.size()):
        var neighbors = []
        for j in range(triangles.size()):
            if i == j: continue
            if are_adjacent(triangles[i], triangles[j]):
                neighbors.append(j)
        neighbors.sort()
        adj.append(neighbors)
    return adj

func triangle_at_point(point: Vector2) -> int:
    for i in range(triangles.size()):
        if is_point_in_triangle(point, triangles[i]):
            return i
    return -1

func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
    var start_id = triangle_at_point(from_point)
    var end_id = triangle_at_point(to_point)

    if start_id == -1 or end_id == -1:
        return PackedInt32Array()
    if start_id == end_id:
        return PackedInt32Array([start_id])

    var path = astar.get_point_path(start_id, end_id)
    if path.is_empty():
        return PackedInt32Array()

    # astar.get_point_path returns positions, we need indices.
    # Actually, astar.get_id_path returns the IDs.
    return astar.get_id_path(start_id, end_id)

func get_centroid(tri: Array) -> Vector2:
    return (tri[0] + tri[1] + tri[2]) / 3.0

func are_adjacent(t1: Array, t2: Array) -> bool:
    var shared = 0
    for i in range(3):
        for j in range(3):
            if t1[i].distance_squared_to(t2[j]) < 0.0001:
                shared += 1
    return shared >= 2

func is_point_in_triangle(p: Vector2, tri: Array) -> bool:
    # Barycentric or simply check if inside polygon (since triangle is a polygon)
    var poly = PackedVector2Array([tri[0], tri[1], tri[2]])
    return Geometry2D.is_point_in_polygon(p, poly)
