func _init():
    # Use barycentric coordinates to check if a point is in a triangle
    var A = Vector2(0,0)
    var B = Vector2(10,0)
    var C = Vector2(4,2)
    var P = Vector2(1,1)

    var v0 = C - A
    var v1 = B - A
    var v2 = P - A

    var dot00 = v0.dot(v0)
    var dot01 = v0.dot(v1)
    var dot02 = v0.dot(v2)
    var dot11 = v1.dot(v1)
    var dot12 = v1.dot(v2)

    var invDenom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    var u = (dot11 * dot02 - dot01 * dot12) * invDenom
    var v = (dot00 * dot12 - dot01 * dot02) * invDenom

    print("u: ", u, " v: ", v, " u+v: ", u+v)
    print("Inside: ", (u >= 0) and (v >= 0) and (u + v <= 1))

    quit()
